import os
import time

import numpy as np
import scipy.fft
import scipy.fftpack

_SMALL_MAX = 256  # n above this always uses the threaded separable FFT path
try:
    _NW = max(1, len(os.sched_getaffinity(0)))
except Exception:  # pragma: no cover
    _NW = max(1, os.cpu_count() or 1)


def _threaded(x):
    # DST-II is separable: transform rows (contiguous) then columns, in place on the temp.
    y = scipy.fft.dst(x, type=2, axis=1, workers=_NW)
    return scipy.fft.dst(y, type=2, axis=0, workers=_NW, overwrite_x=True)


class Solver:
    def __init__(self):
        self._mats = {}
        self._choice = {}

    def _mat(self, n):
        S = self._mats.get(n)
        if S is None:
            k = np.arange(1, n + 1)[:, None]
            j = np.arange(n)[None, :]
            m = (k * (2 * j + 1)) % (4 * n)
            S = 2.0 * np.sin(np.pi * m / (2.0 * n))
            self._mats[n] = S
        return S

    def _run(self, method, x, n):
        if method == 0:
            S = self._mat(n)
            return S @ x @ S.T
        if method == 1:
            return scipy.fftpack.dstn(x, type=2)
        return _threaded(x)

    def _calibrate(self, x, n):
        # Small sizes only: pick the fastest of matmul / fftpack / threaded FFT.
        cands = [0, 1, 2]
        best_m, best_t = 1, float("inf")
        for m in cands:
            for _ in range(3):
                self._run(m, x, n)  # warm-up
            t_min = float("inf")
            for _ in range(6):
                t0 = time.perf_counter()
                self._run(m, x, n)
                t_min = min(t_min, time.perf_counter() - t0)
            if t_min < best_t:
                best_t, best_m = t_min, m
        self._choice[n] = best_m
        return best_m

    def solve(self, problem, **kwargs):
        x = np.asarray(problem)
        if x.ndim != 2 or x.shape[0] != x.shape[1] or x.shape[0] == 0 or x.dtype != np.float64:
            return scipy.fftpack.dstn(problem, type=2)
        n = x.shape[0]
        if n > _SMALL_MAX:
            return _threaded(x)
        m = self._choice.get(n)
        if m is None:
            m = self._calibrate(x, n)
        return self._run(m, x, n)
